import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易经传集解卷十五","description":"周易经传集解 - 周易经传集解卷十五","frontmatter":{"title":"周易经传集解卷十五","description":"周易经传集解 - 周易经传集解卷十五"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/016.md","filePath":"zh/classics/jingchuan-jijie/016.md"}'),r={name:"zh/classics/jingchuan-jijie/016.md"};function c(o,a,l,d,p,h){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易经传集解卷十五",tabindex:"-1"},[n("周易经传集解卷十五 "),e("a",{class:"header-anchor",href:"#周易经传集解卷十五","aria-label":"Permalink to “周易经传集解卷十五”"},"​")],-1),e("p",null,"钦定四库全书周易经传集解坎离卷十五 ​宋林栗撰。序：卦曰：「物不可以终过，故受之以坎。」「坎」者，陷也。「坎」之成卦，「大过」之变也。自「过」之「坎」、「巽」、「兑」，皆变而成也。「坎」者，阳也。「大过」之中爻九三、九四陷而为阴，是以谓之「坎」也。「巽」为木，兑为泽，过乎木、泽而入于陷险之中，是以谓之「坎」也。夫君子者，未尝无过物之志也。天下乱矣，而曰我能治之；国家危矣，而曰我能安之。转祸为福，因败为功，固君子之心也。然而消息盈虚，天之行也。天之所废，虽有过人之才，亦末如之何矣。不知时命而强欲反之，未有不陷焉者也。夏之亡也，有关龙逢；商之亡也，有王子比干。如使有其志而必成其事，为其事而必有其功，则自古无乱亡之国矣。是以大过上六有「过涉灭顶」之凶，「过」而受之以「坎」，斯其义也。习坎，有孚，维心亨，行有尚。彖曰：「习坎」，重险也。水流而不盈，行险而不失其信。「维心亨」，乃以刚中也。「行有尚」，往有功也。天险不可升也，地险山川丘陵也。王公设险以守其国。险之时用大矣哉！下坎上坎成卦曰「坎」者，「乾」「坤」之四象八卦皆「乾」、「坤」也。「乾」之所以不失为「乾」，「坤」之所以不失为「坤」也。震、坎、艮，三阳也。四象八卦，三阳具焉，而不杂乎阴，是其所以不失为震、坎、艮者也。巽、离、坤，三阴也。四象八卦，三阴具焉，而不杂乎阳，是其所以不失为巽、离、兑、坎也。坎坎成卦，初为坎，二为震，三为艮，四又为坎。震，动也；艮，止也。或动或止，而不出乎险陷之中，是以谓之坎也。习坎有孚，何谓也？曰：习者，再也。书曰：卜不习吉。又曰：一习吉。皆再重之义也。至于温习，亦皆本诸再重以言其义耳。故子曰：习坎，重险也。学易者皆读重为平声，取重叠之义。愚谓不然。坎者，险陷之名也，其象水也。地之险陷，水之流行，初无重叠之义，以去声读之。或曰：「敢问其义？」曰：「兑、坎皆水也，兑为泽，坎为川，何也？兑，止水也；坎，流水也。下实上缺，水盈下流，泽之象也。上下皆虚，水行其间，流而不盈，大川之象也。大川之水，日再至焉，是以谓之习坎也，故曰有孚。朝至为潮，夕至为汐，风雨不失其时，晦蚀不差其度，天下之至信，未有过于此者也。故子曰：水流而不盈，行险而不失其信，是之谓有孚也。」说者皆疑八卦唯坎加「习」字，苟不系之以「习」，何以明大川之象乎？「维心亨」，何谓也？曰：坎之二五是也。一阳陷于二阴之中，其体为震，犹人之善溺，身首俱陷，而心独亨也。故说卦坎为通，惟其「心亨」，故无往而不通矣。故子曰：「维心亨，乃以刚中也。」君子遭难而不失其刚中，何险之不济？何困而不亨乎？「行有尚」，何谓也？曰：尚之言配也。自坎而往，则离也。序曰：「陷必有所丽，故受之以离。离者，丽也。」离者，坎之配也。坎为水，离为舟。舟楫之利，以济不通，然后坎之功见矣。不得其配，徒险而已，何功之有哉？故子曰：「行有尚，往有功也。」行则有功，止则无功，其「大川」之谓欤？夫简易者，君子之道也；险阻者，小人之行也。今以险为卦，疑若君子无所取焉，故夫子发明之曰：天险不可升也；地险山川丘陵也，王公设险以守其国。险之时用大矣哉！天若不险，则可阶而升；地若不险，则可平而越。王公不险，则无贵贱之差，内外之限。臣民众庶可得而逾；四邻诸侯可得而侮，将无以守其国矣。险之时用如此，虽君子不可无焉，夫子是以称其大也。王之设险象乎天，公之设险象乎地。子贡曰：「它人丘陵也，犹可逾也。夫子之不可及也，犹天之不可阶而升也。」此王公设险之辨也。象曰：水瀳至，习坎。君子以常德行，习教事。下坎上坎，水瀳至也。水之瀳至，非潮汐之谓乎？是故君子体之，以常德行，习教事。鸡鸣而起，孳孳为善，终日乾乾，夕犹惕若者，常德行也。春夏教以礼、乐，秋冬教以诗、书，春搜夏苗，秋猕冬狩，习教事也。朝以听政，昼以访问，夕以修令，夜以安身，皆是物也。德行之有常，教事之时习，能如水之所至，不失其时，则天下无不可为之事矣。舜何人也？予何人也？有为者亦若是，其习坎之谓乎！子在川上曰：「逝者如斯夫，不舍画夜。」盖将有取于此也。乃若孟子则不然。徐子曰：「仲尼亟称于水，曰：水哉！水哉！何取于水也？」孟子曰：「原泉混混，不舍昼夜，盈科而后进，放乎四海。有本者如是，是之取尔。」此孟子之所见也，其异于沟浍者几希。故孔氏之言水者，自孟子而失之矣。至于老子，则又不然，曰：「水善利万物而不争，处众人之所恶，故几于道。」此老子之所见也。信乎仁者见之谓之仁，智者见之谓之智，亦各随其分量而得之耳。子贡曰：「君子恶居下流，天下之恶皆归焉。」而老子以为几于道，后之君子，将焉取斯？杂卦曰：「离上而坎下也。」凡卦皆以六爻爱恶为吉凶，惟八卦之卦，上下同体，无一爻相应，故不可以杂取其义。惟其位有上下，时有先后，所居之不齐，所遇之不一，则可得而言之矣。离性炎上，其在上卦，则炎上之太过，老也。坎性下流，其在下卦，则下流之已甚者也。下流已甚，故坎下三爻不正而多凶。炎上太过，故离上三爻不正而多惧。惟其二五不失乎中，是以为无咎而已矣。「坎」之九二，不若九五之功。离之六五，不若六二之吉。离上坎下，斯其旨欤？今夫「坎」之所以为水者，一阳陷于二阴之中也。阳为动，为实，水之象也；阴为静、为虚，川之象也。是故「坎」之六爻，其位柔，其画阴，则取譬于川；其位刚，其画阳，则取譬于水。水之至也，见水而不见川，九五是也。及其退也，见川而不见水，六四、上六是也。乃若下卦三爻，初三以阴居刚，而九二以阴居柔，是川与水常相半也。水之不足以实其川，失其故道也；川之不足以虚其水，壅而不流也。故卦为六四，六五无咎，九二以其未出乎中，犹可以小得而已。至于初六、六三不得中行，皆入于坎窞而不能出也。上六、六四虽若同功，然上在一卦之终，见川而不见水，岂非绝流之象乎？是以失道之凶，不同于初六也。初六：习坎，入于坎窞，凶。象曰：「习坎」入「坎」，失道凶也。初六，「坎」也。以阴居刚而在一卦之下，故曰「习坎，入于坎窞」。三画，「坎」也；六画，亦「坎」也。四象八卦皆「坎」也。以「坎」居「坎」，「习坎」之象也。是故初与三、四与上，皆有重「坎」之象焉。「窞」，小「坎」，水之旁入也。下卦之下而又遇「坎」焉，「入于坎窞」之象也。阳为动，阴为止。当「坎」之初、动之时也，「入于坎窞」，止而不行，是为弃水矣。水流而不盈，行险而不失其信，故虽纵横万折，极其济物之功，而进退迟疾不失其常度，是以贵乎「习坎」也。若失其道而入于坎窞之中，则窞而不能自出矣，欲无凶，得乎？是以君子恶居下流也，故曰「凶」。子曰：「习坎入坎，失道，凶也。」或曰：川之犹为泽也，曷谓其弃之哉？曰：所贵乎川者，为其不舍昼夜，流行而不息也。若壅而为泽，则无利涉之功，无日新之德矣。谓之弃水，不亦宜乎？是故「坎」为阳，「兑」为阴；阳为君子，阴为小人。君子之弃而小人之归，是以为失道之凶也。九二：坎有险，求小得。象曰：「求小得」，未出中也。九二，震也。以阳居柔，而在下卦之中，故曰「坎有险」。「震」，动也；「坎」，陷也。动乎险陷之中，而不当其位，「坎有险」之象也。夫大川之水，无险不平。今居下而有险焉，则溅溅之流也。然而未出乎中，故曰「求小得」。传曰：「水之积也不厚，则其负大舟也无力。复杯水于坳堂之上，则芥为之舟；置杯焉则胶，水浅而舟大也。」然则九二之水，不足以行大舟，近者求济，小有得而已，不能无所不通如九五也。子曰：「求小得，未出中也。」若居下流而又出乎中，则「入于坎窞」矣，何「小得」之云乎？六三：来之坎坎，险且枕，入于坎窞，勿用。象曰：「来之坎坎」，终无功也。六三上体为「艮」，下体为「坎」，以阴居刚而在下卦之上，故曰「来之坎坎」。「来」，下「坎」也；之上亦「坎」也，故曰「险且枕」。按陆氏著义，「枕」，古本作「沈」，直林反，传写误耳。「沈」，深也。下「坎」上「艮」，「坎」为水，「艮」为山，水在山下，险且深也。「坎」，陷也；「艮」，止也。以六居三，不当其位，陷而止，无出阴之象，故曰「入于坎窞」。或曰：初六在卦之最下，故有坎陷之象。六三在下卦之上，而亦为坎陷，何哉？曰：百川旁大，未必皆下流也。下流而失之者，初六是已；中流而失之者，六三是已。要之，不得乎中，不当其位，止而不行，失其故道而已矣，故曰「勿用」。初居下流，其势不能自反，是以遂成于凶。三在上下之交，进退之地，其邪正中偏，惟其所趋，故戒以「勿用」而已。子曰：「来之坎坎，终无功也。」夫济人于险难之中，而措之于平夷之地，「坎」之所以为功也。来往皆险，又何功之有哉？六四：樽酒簋贰，用缶，纳约自牖，终无咎。象曰：「樽酒簋贰」，刚柔际也。六四上体为「坎」，下体为「艮」，以阴居柔而在上卦之下，故曰「樽酒簋贰，用缶，纳约自牖」。「酒」，阳也；「食」，阴也。一阳二阴，「坎」之数也。「缶」，瓦器也。诗曰「坎其击缶」是也。「牖」，室前也。礼曰「饭于牖下」是也。「约」，剂也。周官：「司约掌邦国及万民之约剂，治人之约为上，凡大约剂书于宗彝，小约剂书于丹图。」郑氏曰：「剂谓劵书。神约，谓命祀郊社群望及所祖宗也。」然则古者王侯至于万民，其国家之典祀，皆有约剂，其不能修祝嘏者，约约剂而已。「缶」，声之所从出；「牖」，约之所自入，皆「坎」之象也。礼曰：「鼎俎奇而笾豆偶，阴阳之义也。」尔雅：「大琴谓之离，小罍谓之坎。」琴谓之离者，形中虚而外实也；罍谓之坎者，形中实而上下皆虚也。古之制器尚象盖如此。故「玄酒在室，醴𬪨在户，粢醍在堂，澄酒在下」，则酒醴之用，不一而足也。三牲之俎，八簋之实，水草之菹，陆产之致，则品物之荐，非二而已也。若夫六律、八音，所以妥侑；六祝、六祈，所以昭告；五几、六席，所以辨位，其礼乐之备，至孔子且有所不知。今也一樽之酒，二簋之食，其乐用缶，其告用约，纳之自牖，可谓简且陋矣。然而君子以是而为礼，鬼神以是而来歆者，贵其有常而不失信也。损之彖曰：「曷之用？二簋可用享。」凶荒扎瘥，与时俱损也。此言「樽酒簋贰用缶，纳约自牖，终无咎」者，朝夕之奠，不失其常也。诗云：「于以采苹，于以采藻，于以奠之，宗室牖下。谁其尸之？有齐季女。」说者曰：「女教既成，告于祖庙，牲用鱼，芼之以苹藻，所以成妇顺也。」以愚观之，于义未该。采蘩之序曰：「夫人不失职也。夫人可以共祭祀，则不失职矣。」采苹之序曰：「大夫妻能循法度也。」能循法度，则可以承先祖，共祭祀矣。自天子至于庶人，饮食不敢忘其先，故公侯大夫之家，朝夕必祭。采蘩采苹，朝夕之祭也。祭必有尸，无尸曰奠。故其诗云：「奠于牖下」，而使季女尸之，以明其专且洁也。「被之僮僮，夙夜在公」，以明其不失常也。故曰：「苟有明信，涧溪沼沚之毛，苹蘩蕰藻之菜，筐筥锜釜之器，潢污行潦之水，可以荐于鬼神，羞于王公者，昭忠信也。」若夫女教既成，牲用鱼，芼之以苹藻，亦习为妇道而已矣。然则「樽酒簋贰用缶，纳约自牖」，其亦采蘩采苹之义乎？然而系之坎六四，何也？四居上下之交，进退之地，其体坎艮，陷而止，与六三均耳。三为「来之坎」，坎险且沈，「入于坎窞」。四为「樽酒簋二用缶，纳约自牖」，皆「坎」象也。三在下卦之上，而四在上卦之下，三以阴居刚，四以阴居柔故也。夫「坎」之成卦，取诸水也。阳为水，阴为川。下卦之上，以阴居刚者，水至而川见也。上卦之下，以阴居柔者，水退而川见也。水至而川见，陷而止者，失其道而入于坎陷也。水退而川见，陷而止者，行险而不失其信也。夫水之至也，可以言其利涉之功；及其退也，言其不失信而已。人之平居，所以致其诚信者，未有于君父神明之为至。郊祀之礼，禘尝之事，致爱则存，致悫则著，然未若一饭必祭之为不妄也。故以「樽酒簋二用缶纳约，自牖」明之。君子之道，于是为有孚矣。故曰：「终无咎。」夫礼虽简而信已孚，物虽薄而诚已至，神之所飨，不在兹乎？是以「终无咎」也。子曰：「樽酒簋贰，刚柔际也。」一奇而二耦，樽圆而簋方。六四以阴居柔，而爻具斯象者，岂非上接九五，刚柔相际，以是而言之乎？或问：二四有坎，兼艮之体，二爻之象，曷为不取诸「艮」欤？曰：此八纯之卦，非五十六卦之比也。方其未重也，既以为「坎」矣。及其重之，又不失为「坎」也。虽六画既成，有「震」有「艮」，而不足以易其本象，是故六爻皆取诸「坎」也。若夫二五为行，三四为止，非其所取于「震」、「艮」者欤？九五：坎不盈，祗既平，无咎。象曰：「坎不盈」，中未大也。九五，「震」也。以阳居刚，而在上卦之中，故曰：「坎不盈，祗既平。」「震」，动也；「坎」，陷也。以阳刚之才，动乎险陷之中，水流而不盈也。「祗」，适也；以九五居中而不过，适至于平也。水之流行，适至于平而已，舟楫之利，于是乎赖之，此象所谓「行有尚」者也。过乎平则溢而失道，入于坎窞矣。水失其道，舟欲安行，不可得也，故曰：「无咎。」子曰：「坎不盈，中未大也。」言其得中而未至于大，是以为「无咎」也。说者乃以其未大而少之，则失之矣。潮汐之至，有小有大。九二为小，九五为平，是以言未大也。大斯盈，盈斯溢矣。夫所以陷者，为其过也。故曰：「物不可以终过，故受之以坎。」然则君子之取于「坎」者，求其平而不求其大也。故曰：「中庸之为德也，其至矣乎！」由是言之，孟子所谓「不盈科不行」者，盖亦未尝观其澜也。夫六四之有其信，九五之有其功，可谓吉矣。不曰「吉」而曰「无咎」者，坎险难之象也。利涉而无咎者，吉可知矣。上六：系用徽𬙊，置于丛棘，三岁不得，凶。象曰：上六失道，凶三岁也。上六，「坎」也，以阴居柔，而在上卦之上，故曰：「系用徽𬙊，置于丛棘。」徽𬙊，索也；丛棘，刺也。上，「坎」之中，时之极也。见川而不见水，若将终焉者，是失其道而绝其流也。然则「系用徽𬙊，置于丛棘」，其败舟之象乎？故曰：「三岁不得，凶。」自四至上三爻，故有三岁之象。水之瀳至不失其时，则舟之往来不改其常。川竭而废舟，至于三岁之久而不得其道，凶可知矣。九家易：「坎为丛棘，为桎梏」，故又有刑狱之象。丛棘，如今之棘围，所以限囚之出入也。说者谓王之外朝，左右九棘，大司寇听刑于棘木之下，非其义矣。棘以木言者，枣也；以丛言者，刺也。今言「丛棘」，是丛生之棘，非九棘之谓也。系而置之，非朝位之称也。险之时用，君子固有不得已焉，盖将以出险而已。今在一卦之上，而以险终之，是甘心于行险者也。「系用徽𬙊，置于丛棘」，不亦宜乎？故子曰：「上六失道，凶三岁也。」周官用圜，凡害人者，置之圜上，而加明刑焉。其能改者，上罪三年而舍；其不能改而出圜上者，杀。易之所谓「三岁不得」者，其不能改而出圜上者乎？是以系之「凶」也。序卦曰：「陷必有所丽，故受之以离。」离者，丽也。「离」之成卦，「坎」之变也。自「坎」之「离」，六画尽变而成也。「坎」者，陷也。「离」者，丽也。一阳在二阴之中，其势不得不陷，是以谓之「坎」也。一阴在二阳之中，其势不得不丽，是以谓之「离」也。阳为上，阴为下，阳陷于阴，则上者下矣，是故「坎」自上而下流者也。阴丽于阳，则下者上矣，是故「离」自下而炎上者也。阳为明，阴为晦，阳陷于阴，则其明晦矣，是故「坎」内明而外晦者也。阴丽于阳，则其晦明矣，是故「离」内晦而外明者也。自上而下流，内明而外晦，水之象也，「坎」之所以为水也。自下而炎上，内晦而外明，火之象也，「离」之所以为火也。水火之情如此其相远也。然而「坎」实阳也，「离」实阴也。君子小人，顾其所以自处如何耳。陷其高明则为小人，抗其卑晦则为君子，岂可常也哉？故曰：「陷必有所丽，故受之以离。」言物无终陷之理，陷而思出，则必丽乎阳矣。得其所丽，反昏以为明，去狂而入圣，舍桀、跖而为尧、颜，孰能御之？受之以「离」，斯其义也。离：利贞，亨。畜牝牛，吉。象曰：「离」，丽也。日月丽乎天，百谷草木丽乎土，重明以丽乎正，乃化成天下。柔丽乎中正，故「亨」。是以「畜牝牛，吉」也。下离上「离」，成卦曰「离」者，初为「离」，二为「巽」，三为「兑」，四又为「离」。「巽」，伏也；「兑」，见也。或伏或见，而皆有所丽焉，是以谓之「离」也。「离，利贞，亨」，何谓也？曰：「离」，丽也；「贞」，正也。「离」非能自亨，丽于正而后亨也。观其所离而丽之，吉凶可见矣。正也者，二五之谓也。二五为中，中则正矣。所以然者，「离」本「乾」也，阴丽其中而成「离」。「坎」本「坤」也，阳陷其中而成「坎」。是故离之二五，地二之火升乎天也；坎之二五，天一之水行乎地也。夫子于是推明丽物而著见之义曰：日月丽乎天，百谷草木丽乎土，重明以丽乎正，乃化成天下。柔丽乎中正故亨。日月者，阴阳之精也。阴阳之精不能以自明也，丽乎天而后明。何者？天，积阳之气，日月之所待而明也。百谷草木者，阴阳之质也。阴阳之质不能以自形也，丽乎土而后形。何者？土，积阴之气，百谷草木之所待而形者也。重明者，以明继明，帝王之象也。书称帝舜曰「重华协于帝」，又称文王、武王「宣重光奠丽」是也。夫以渺然之身，而居亿兆之上，力能光被四表，如日月之照临，不丽乎正，何以能化成天下哉？故曰：昔在文武，聪明齐圣。小大之臣，咸怀忠良。其侍御仆从，罔匪正人。以旦夕承弼厥辟，出入起居，罔有不钦。发号施令，罔有不臧。下民祇若，万邦咸休。此则重明丽正，以化成天下之义也。天地之道，贞观者也。日月之道，贞明者也。天下之动，贞夫一者也。一者何也？中正之谓也。柔之为道，伏则为巽，见则为兑。惟其丽乎中正，是以能一天下之动也。日月中天，而后万物不能逃其照，其丽正之谓乎！「畜牝牛吉」，何谓也？曰：牛，顺物也。牝牛又其顺者，六二是也。二、五皆有「巽」之象焉。「巽」也者，「小畜」、「大畜」之所以为畜者也。「大畜」之所畜者，阳也，故其象为马之逐者、牛之角者、豕之牙者。「离」之所畜者，阴也，故其象为牝牛而已。大小畜畜阳而离畜阴，何也？曰：「小畜」之所以能畜者，五阳而一阴也。「大畜」之所以能畜者，二阳同体而合志也。今虽有二阴各主一卦，而不相应，其为畜也难矣。非六二之至顺，何以能畜之哉？是故以五而畜四，则有「焚如」之难；以五而畜三，则兴大耋之嗟。是二阳皆不受其畜也。二阳，「离」、「兑」也，犹不可畜，而况于「乾」乎？离、兑不可畜，则「巽」亦不可畜矣。然而六二为之畜者也，曰此则爻象之变化也。二，「巽」也。五既为「巽」，则二之象变矣。自五至三，「巽」、离、兑，则六二以阴居柔，其「坤」之象乎？「坤」也者，天下之至顺也。「坤」为母，为牛，是以谓之「牝牛」也。夫自三至四，自五至三，「巽」、「离」、「兑」均也，而独立六二为「坤」者，岂非以位言之乎？五刚而二柔，五贵而二贱，五在天而二在地也。故子曰：「重明以丽乎正，乃化成天下。柔丽乎中正，故亨。是以畜牝牛吉也。」六二既为所畜矣，二四虽欲违之，而不可得也。何者？「巽」、「离」、「兑」皆「坤」之女也，其母归之，其子焉往取诸牝牛，斯其义欤？夫推天下之至顺，如伊尹、周公而为天下之所归，商周之王，重明丽正，得而畜之，是为「吉」矣。夫八纯之卦，本不以六爻相错成文，而「离」之成卦，只以阴丽阳为义。初九畜德养贤之象。圣人因六五有继明之义，而六二有至顺之资，拟议以成其变化，故系之以「畜牝牛吉」。信乎引而伸之，触类而长之，无往而不通矣。象曰：明两作，「离」，大人以继明照于四方。下离上离，明两作也。天无二日，何谓「明两」？其两曜之象乎？或曰：月，坎也，而谓之「离」，何也？曰：月之所以为「坎」者，水之精也。日之所以为「离」者，火之精也。夫火无定形，丽于物而后著见者也。故有以阳燧而得之者，有以阴燧而得之者。夫阳燧则火之精，而阴燧则水之精也。故夫日之所以其光赫然者，火也；月之所以其光湛然者，水也。然其所以为明，则皆取诸离也。是故月与日会而后世明，与日相望而后大明，岂非其取诸「离」耶？故曰：「大人以继明照于四方。」继明之象，在天为日月，在人为君臣。而比象之辞，盖以帝王继世为义，非君臣之谓也。舜之重华，武之重光，斯其义矣。杂卦曰：「离上而坎下也。」上下之义，已见前卦。离之所以为明者，一阴丽乎二阳之间也。下卦为昼，上卦为夜，六爻之义，皆取诸离。观其所丽，而吉凶可见矣。九丽于初，下卦之始，日之出也。六丽于二，下卦之中，日之正也。九丽于三，下卦之终，日之昃也。九丽于四，上卦之始，月之出也。六丽于五，上卦之中，月之正也。九丽于上，上卦之终，月之入也。夫大人者，与日月合其明者也。故上下二卦，以日月重明为象，以大人继明为义。然析而言之，则日，君象也；月，臣象也。以臣而言君道不可也。故下卦言日，而上卦不言月也。初上二爻，不见始终之义，何也？曰：易之为书，触类而长，不以辞费。二为「黄离」，三为日昃，四为「焚如」，则继明之叙粲然矣。初上又言终始之义，不既赘矣。离，南方之卦，有文明之象，故为礼；有威武之象，故为兵。是以初九著礼文之义，上九言征伐之事，所以互见之也。礼者，下人者也，治之本也，是以系之于初。兵者，上人者也，治之末也，是以系之于上也。初既言「履」，而又言「敬」。敬也者，礼之本也。上既言「征」，而又言「获」。获也者，兵之末也，亦终始之义也。推六五一爻，既不可取象于月，故直以主少国危明其义耳。初九，履错然，敬之，无咎。象曰：「履错」之「敬」，以辟咎也。初九，「离」也。以阳居刚，而在下卦之下，故曰「履错然，敬之」。「履」者，礼也。「离」为文明，礼之象也。「错」，杂也。三画，「离」也；六画，亦「离」也；四象八卦，皆「离」也。以「离」居「离」，礼文错然之象也。夫礼者，下人者也。敬也者，礼之本也。敬者，质也。礼者，文也。阳为质，阴为文。以阳刚之德，居文明之初，而在卦之最下，为礼而能敬者也，故曰「无咎」。礼不错则不成，文繁则乱。当礼文错杂之时，惟敬为本，斯可以免于咎矣。故子曰：「履错之敬，以辟咎也。」孔子曰：「祭与其敬不足而礼有余，不若礼不足而敬有余也；丧与其哀不足而礼有余，不若礼不足而哀有余也。」其「辟咎」之谓乎？六二：黄离，元吉。象曰：「黄离，元吉」，得中道也。六二，「巽」也。以阴居柔而在下卦之中，故曰「黄离」。「黄」，中也；「离」，明也；「巽」，入也。入乎离明之中，「黄离」之象也。日之出也，其色赤；及其中天也，其色黄，是以谓之「黄离」也。险为虚，下为谦，中为正，体乎谦虚而丽乎中正，舍己从人，以天下为明者也，故曰「元吉」。如日中天，无所不照，非「元吉」，何以当之？或曰：六二以阴居柔而位乎地，人臣之道也。而以为火明之象，何哉？曰：此八纯之卦，不以相应为义者也。子曰：「柔丽乎中正，故亨。」六二之谓也。及其重为上卦，则是继明也，故曰：「重明以丽乎正，乃化成天下。」六五之谓也。后明既升，则前明已没，故六二有「牝牛」之象也。谓五为君，谓二为臣，则失之矣。「坤」之六五曰：「黄裳，元吉。」虽在天位，而臣道也，配「乾」而称「裳」也。「离」之六二曰：「黄离，元吉。」虽在地位，而君道也，丽正而称「离」矣。故子曰：「黄离元吉，得中道也。」虽有尧舜之聪明，而不得乎中道，其能光宅天下也哉？九三：日昃之离，不鼓缶而歌，则大耋之嗟，凶。象曰：「日昃之离」，何可久也？九三上体为「兑」，下体为「离」，以阳居刚，而在下卦之上，故曰：「日昃之离」。「离」，明也，日过中则昃矣。离为日，「兑」为夕；下卦为昼，上卦为夜。九三下卦之终，日昃之象也。日昃之明，其为明也不久矣。故曰：「不鼓缶而歌，则大耋之嗟，凶。」缶，瓦器也，鼓之所以节歌。按庄周鼓盆而歌，蔺相如进盆，并请秦王击缶。汉杨恽仰天击缶而歌乌乌。风俗通曰：「缶所以盛酒浆，秦人鼓之以节歌。」诗曰：「坎其击缶，宛邱之道。」则鼓缶不特秦声也，简陋之器，中国通用之。故坎言「樽酒簋贰用缶」，此言「鼓缶而歌」，皆坎象也。离者，坎之变也，故有不鼓缶之象焉。子曰：张而不弛，文武弗能也。弛而不张，文武弗为也。一张一弛，文武之道也。故君子于向晦宴息之时，饮酒以娱乐，鼓缶而啸歌可也。耋，老也。八十曰耄，九十曰耋。兑为日昃，故有大耋之象。又为口，故有歌嗟之象。夫有盛必有衰，有壮必有老，有始必有终，有生必有死，物之常也。故夫日昃者，一日之老也；秋冬者，一岁之老也；耄耋者，百年之老也。乐天知命，安时处顺，则日昃而啸歌，岁终而饮蜡，耋老而优游，无日而不自得矣。不能乐天知命，而有老大之嗟，终能免于死乎？故曰「凶」。诗云：「子有酒食，何不日鼓瑟？且以喜乐，且以永日。宛其死矣，他人入室。」其斯之谓也。或曰：「鼓缶而歌，与大耋之嗟，惧不逃乎昼夜之数，则圣人何取于歌乐乎？」曰：此为耄荒者之戒也。人之聪明固有限量，老虽智而耄及之矣。强昏以为明，若倦以为勤，一日二日万几，其失也多矣。释其重任，优游卒岁，上智之事也。是以尧之耄期，则求贤而逊之位，及其殂落，百姓如丧考妣。穆王耄荒，方且作刑以经四方，周道于是衰微。此则歌嗟之辨也。故子曰：「日昃之离，何可久也？」「蛊」之上九，贵乎「高尚其事」；「离」之九三，贵乎「鼓缶而歌」。消息盈虚，与时偕行之义也。九四：突如其来如，焚如，死如，弃如。象曰：「突如其来如」，无所容也。九四上体为「离」，下体为「兑」，以阳居柔，而在上卦之下，故曰「突如其来如」。六四继明之初，而不当其位，不顺之子也。其体为「兑」，「兑」居酉位，昼夜之交，昏瞑之际，月将升而未明也。而其体为「离」，「离」为火。日之既入，月之方升，而有赫然之明，突然而来者，燎原之火也。古者谓子不顺为「突」。九三耋而不传，九四不待其萌而传。悖逆之节，譬若燎原之火，「突如其来如」也。州吁、商臣，是其人矣。故曰：「焚如，死如，弃如。」书曰：「若火之燎于原，不可向迩，其犹可扑灭。」「焚如」者，不可向迩也。「死如，弃如」者，犹可扑灭也。古者凶人之丧，不居兆域，死而弃之，投畀豺虎，天地人神之所不容也。故子曰：「突如其来如，无所容也。」突，一作突。六五：出涕沱若，戚嗟若，吉。象曰：六五之「吉」，离王公也。六五，巽也。以阴居刚，而在上卦之中，故曰：「出涕沱若，戚嗟若。」六五，继明而丽正者也。何谓正？曰：天下之动，贞夫一者也。君父之所命，国人之所立，斯为正矣。然而以柔居尊，而有九四之逼，凶焰炽烈，不可向迩，故至于涕泣而忧嗟。「巽」为多白眼，故有出涕、戚嗟之象。夫继统守成之君，生于深宫之中，长于妇人之手，未尝知哀，未尝知忧，未尝知惧，自非上圣，鲜不以逸豫骄奢而失之者。方其嗣位之初，遭家多难，至于出涕而忧嗟，乃所以为之儆戒也，故曰「吉」。六五体巽而承于上九，其亦信顺尚贤之义乎？是以系之吉也。子曰：六五之吉，离王公也。「离」，丽也。王公者，以位言之也。在天下为王，在一国为公也。位也者，圣人之大宝也。位定而不敢争者，逆顺之形判矣。启既嗣位，天下皆曰：吾君之子也。虽有扈之强，乌能陵之哉？上九，王用出征，有嘉折首，获匪其丑，无咎。象曰：「王用出征」，以正邦也。上九，离也。以阳居柔，而在一卦之上，故曰「王用出征」。六五，王也，而九居其上，王之所用以出征也。离为甲胄，为戈兵，故有出征之象。诗云：「王于出征，以匡王国。王于出征，以佐天子」是也。管蔡之难，周公东征，应其义矣。故曰「有嘉折首，获匪其丑」。嘉，美也，谓有功也，犹言肤功美绩是也。或曰：嘉，配也。六爻无应，故六五之于上九得称「嘉」也。首，元恶也，歼厥渠魁，胁从罔治，「折首」之谓也。丑，类也，自西自东，自南自北，无思不服，「获匪其丑」之谓也。九四体兑，兑为毁折，故有「折首」之象。下卦三爻，虽非其应，而皆为所畜，故有「获匪其丑」之象。诗云「执讯获丑」，而此言「获匪其丑」者，武王克商，通道于九夷八蛮，成王既伐东夷，肃慎来贺，斯其义矣。故曰：「四征弗庭，绥厥兆民，六服群辟，罔不承德，又何咎之有哉！」故子曰：「王用出征，以正邦也。」征之为言正也，征一而正百，斯之谓正邦也。不曰「吉」而曰「无咎」者，干戈之事，无咎为难矣。王肃本下有二句：「获匪其丑，大有功也。」今本脱之。周易经传集解坎离卷十五。",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
